(() => { 
  let textEl = document.evaluate("//div[text()='Text']", document, null, XPathResult.FIRST_ORDERED_NODE_TYPE, null).singleNodeValue;
  let parent = textEl;
  for (let i = 0; i < 10; i++) {
    let style = window.getComputedStyle(parent);
    if (parent.tagName === 'BUTTON' || parent.tagName === 'A' || parent.getAttribute('role') === 'button' || style.cursor === 'pointer') {
      let rect = parent.getBoundingClientRect();
      return JSON.stringify({x: rect.x + rect.width/2, y: rect.y + rect.height/2, tag: parent.tagName, classes: parent.className});
    }
    parent = parent.parentElement;
  }
  return 'not found';
})()
